/**
 * Auth Integration Tests
 * Generated by BackendForge
 */
const request = require('supertest');
const app = require('../src/app');

describe('Auth API', () => {
  // ─── Registration ─────────────────────────────────────
  describe('POST /api/auth/register', () => {
    it('should register a new user', async () => {
      const res = await request(app)
        .post('/api/auth/register')
        .send({
          name: 'Test User',
          email: `test-${Date.now()}@example.com`,
          phone: '+911234567890',
          password: 'Test@12345',
        });
      expect(res.statusCode).toBe(201);
      expect(res.body.success).toBe(true);
      expect(res.body.data.user).toBeDefined();
      expect(res.body.data.user.email).toBeDefined();
      expect(res.body.data.user.passwordHash).toBeUndefined(); // Should not leak
      expect(res.body.data.accessToken).toBeDefined();
      expect(res.body.data.refreshToken).toBeDefined();
    });

    it('should reject duplicate email', async () => {
      const email = `dup-${Date.now()}@example.com`;
      await request(app).post('/api/auth/register').send({
        name: 'User 1', email, password: 'Test@12345',
      });
      const res = await request(app).post('/api/auth/register').send({
        name: 'User 2', email, password: 'Test@12345',
      });
      expect(res.statusCode).toBe(409);
    });

    it('should reject weak password', async () => {
      const res = await request(app)
        .post('/api/auth/register')
        .send({ name: 'Weak', email: 'weak@test.com', password: '123' });
      expect(res.statusCode).toBe(400);
    });
  });

  // ─── Login ────────────────────────────────────────────
  describe('POST /api/auth/login', () => {
    const testEmail = `login-${Date.now()}@example.com`;

    beforeAll(async () => {
      await request(app).post('/api/auth/register').send({
        name: 'Login Test', email: testEmail, password: 'Test@12345',
      });
    });

    it('should login with correct credentials', async () => {
      const res = await request(app)
        .post('/api/auth/login')
        .send({ email: testEmail, password: 'Test@12345' });
      expect(res.statusCode).toBe(200);
      expect(res.body.success).toBe(true);
      expect(res.body.data.accessToken).toBeDefined();
    });

    it('should reject wrong password', async () => {
      const res = await request(app)
        .post('/api/auth/login')
        .send({ email: testEmail, password: 'WrongPass1' });
      expect(res.statusCode).toBe(401);
    });
  });

  // ─── Protected Routes ─────────────────────────────────
  describe('Protected endpoints', () => {
    it('should reject unauthenticated requests', async () => {
      const res = await request(app).get('/api/users/profile');
      expect(res.statusCode).toBe(401);
    });

    it('should accept authenticated requests', async () => {
      const regRes = await request(app).post('/api/auth/register').send({
        name: 'Auth Test', email: `auth-${Date.now()}@test.com`, password: 'Test@12345',
      });
      const token = regRes.body.data.accessToken;
      const res = await request(app)
        .get('/api/users/profile')
        .set('Authorization', `Bearer ${token}`);
      expect(res.statusCode).toBe(200);
    });
  });

  // ─── Health Check ─────────────────────────────────────
  describe('GET /api/health', () => {
    it('should return healthy status', async () => {
      const res = await request(app).get('/api/health');
      expect(res.statusCode).toBe(200);
      expect(res.body.status).toBe('healthy');
    });
  });
});
